<?php
/** Default public Blog fragment: semantic cards, typed escaped blocks, author/archive navigation and native moderated comment form. Public copy belongs to this view/template, not admin dictionaries. */
declare(strict_types=1);
use DBLESSCMS\{BlogView,BlogModel,Security};
use function DBLESSCMS\e;
$catalog=$blogModel['catalog'];$publication=$blogSettings['publication'];
/** Render an article card from a validated published projection; takes article, writes semantic escaped HTML and performs no I/O. */
$card=static function(array $item) use($catalog,$publication,$base_url): void { ?>
<article class="blog-card" data-blog-card>
  <?php if ($item['cover']!==''): ?><a class="blog-card-image" href="<?= e(BlogView::url($base_url,'article',['slug'=>$item['slug']])) ?>" tabindex="-1" aria-hidden="true"><img src="<?= e(BlogView::media($base_url,$item['cover'])) ?>" alt="" loading="lazy" width="1280" height="720"></a><?php endif; ?>
  <div class="blog-card-content"><p class="blog-eyebrow"><?php if ($item['featured']): ?><span>Featured</span> · <?php endif; ?><time datetime="<?= e($item['publishedAt']) ?>"><?= e(substr($item['publishedAt'],0,10)) ?></time></p><h2><a href="<?= e(BlogView::url($base_url,'article',['slug'=>$item['slug']])) ?>"><?= e($item['title']) ?></a></h2><p><?= e($item['excerpt']) ?></p><p class="blog-meta"><?= e($catalog['authors'][$item['author']]['name']??'') ?> <span aria-hidden="true">·</span> <?= BlogModel::readingTime($item,$publication['readingSpeed']) ?> min read</p><a class="blog-read" href="<?= e(BlogView::url($base_url,'article',['slug'=>$item['slug']])) ?>">Read article <span class="sr-only"><?= e($item['title']) ?></span><span aria-hidden="true"> ↗</span></a></div>
</article>
<?php }; ?>
<?php if (!isset($manifest['partials']['blog'])): ?><link rel="stylesheet" href="<?= e(\DBLESSCMS\asset('plugins/blog/css/public.css',$base_url)) ?>"><?php endif; ?>
<section class="blog" aria-label="<?= e($publication['title']) ?>"><div class="blog-container">
<?php if ($blogModel['kind']==='list'): ?>
<header class="blog-hero"><p class="blog-eyebrow">Journal &amp; ideas</p><h1><?= e($page['meta']['title']) ?></h1><p class="blog-lead"><?= e($page['meta']['description']) ?></p><div class="blog-links"><a href="<?= e(BlogView::url($base_url,'feed')) ?>">RSS feed</a><a href="<?= e(BlogView::url($base_url,'sitemap')) ?>">Sitemap</a></div></header>
<form class="blog-search" method="get" action="<?= e(BlogView::url($base_url)) ?>"><label>Search articles<input type="search" name="q" maxlength="128" value="<?= e($blogModel['query']['q']) ?>"></label><label>Category<select name="category" aria-label="Category"><option value="">All categories</option><?php foreach ($catalog['categories'] as $category): if ($category['deleted']) continue; ?><option value="<?= e($category['id']) ?>" <?= $blogModel['query']['category']===$category['id']?'selected':'' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><?php foreach (['tag','author'] as $filter): if ($blogModel['query'][$filter]==='') continue; ?><input type="hidden" name="<?= e($filter) ?>" value="<?= e($blogModel['query'][$filter]) ?>"><?php endforeach; ?><button type="submit">Search</button><?php if (array_filter($blogModel['query'],static fn(string $value,string $key): bool=>$value!==''&&$key!=='page',ARRAY_FILTER_USE_BOTH)!==[]): ?><a href="<?= e(BlogView::url($base_url)) ?>">Clear filters</a><?php endif; ?></form>
<?php if ($blogModel['articles']===[]): ?><p class="blog-empty" role="status">No articles matched this selection.</p><?php else: ?><p class="blog-meta"><?= $blogModel['total'] ?> articles</p><div class="blog-grid"><?php foreach ($blogModel['articles'] as $item) $card($item); ?></div><?php endif; ?>
<?php if ($blogModel['pages']>1): ?><nav class="blog-pagination" aria-label="Article pages"><?php if ($blogModel['number']>1): ?><a rel="prev" href="<?= e(BlogView::url($base_url,'list',array_replace($blogModel['query'],['page'=>(string)($blogModel['number']-1)]))) ?>">← Previous</a><?php endif; ?><span aria-current="page"><?= $blogModel['number'] ?> / <?= $blogModel['pages'] ?></span><?php if ($blogModel['number']<$blogModel['pages']): ?><a rel="next" href="<?= e(BlogView::url($base_url,'list',array_replace($blogModel['query'],['page'=>(string)($blogModel['number']+1)]))) ?>">Next →</a><?php endif; ?></nav><?php endif; ?>
<?php else: $article=$blogModel['article'];$author=$catalog['authors'][$article['author']]??null; ?>
<?php if ($blogModel['preview']): ?><p class="blog-notice" role="status">Authenticated preview · saved version · <?= e(BlogModel::status($article)) ?></p><?php endif; ?>
<nav class="blog-breadcrumb" aria-label="Breadcrumb" itemscope itemtype="https://schema.org/BreadcrumbList"><span itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem"><a itemprop="item" href="<?= e(BlogView::url($base_url)) ?>"><span itemprop="name"><?= e($publication['title']) ?></span></a><meta itemprop="position" content="1"></span> <span aria-hidden="true">/</span> <span itemprop="itemListElement" itemscope itemtype="https://schema.org/ListItem" aria-current="page"><span itemprop="name"><?= e($article['title']) ?></span><meta itemprop="item" content="<?= e($contentMetadata['canonical']) ?>"><meta itemprop="position" content="2"></span></nav>
<article class="blog-article" itemscope itemtype="https://schema.org/BlogPosting">
<header class="blog-article-header"><div class="blog-chips"><?php foreach ($article['categories'] as $category): ?><a href="<?= e(BlogView::url($base_url,'list',['category'=>$category])) ?>"><?= e($catalog['categories'][$category]['name']) ?></a><?php endforeach; ?></div><h1 itemprop="headline"><?= e($article['title']) ?></h1><p class="blog-lead" itemprop="description"><?= e($article['excerpt']) ?></p><p class="blog-meta"><?php if ($author!==null): ?><a href="<?= e(BlogView::url($base_url,'list',['author'=>$author['id']])) ?>" rel="author"><?= e($author['name']) ?></a> · <?php endif; ?><?php if ($article['publishedAt']!==''): ?><time itemprop="datePublished" datetime="<?= e($article['publishedAt']) ?>"><?= e(substr($article['publishedAt'],0,10)) ?></time> · <?php endif; ?><?= BlogModel::readingTime($article,$publication['readingSpeed']) ?> min read</p><meta itemprop="dateModified" content="<?= e($article['updatedAt']) ?>"><link itemprop="mainEntityOfPage" href="<?= e($contentMetadata['canonical']) ?>"></header>
<?php if ($article['cover']!==''): ?><figure class="blog-cover"><img itemprop="image" src="<?= e(BlogView::media($base_url,$article['cover'])) ?>" alt="<?= e($article['coverAlt']) ?>" width="1280" height="720" fetchpriority="high"></figure><?php endif; ?>
<div class="blog-reading-layout"><aside class="blog-toc" aria-label="On this page"><h2>On this page</h2><ol><?php foreach ($article['blocks'] as $position=>$block): if ($block['type']!=='heading') continue; ?><li><a href="#blog-section-<?= $position ?>"><?= e($block['text']) ?></a></li><?php endforeach; ?></ol><a href="<?= e(BlogView::url($base_url,'feed')) ?>">Subscribe with RSS ↗</a></aside><div class="blog-body" itemprop="articleBody">
<?php foreach ($article['blocks'] as $position=>$block): switch ($block['type']): case 'paragraph': ?><p><?= e($block['text']) ?></p><?php break;case 'heading': if ($block['level']===3): ?><h3 id="blog-section-<?= $position ?>"><?= e($block['text']) ?></h3><?php else: ?><h2 id="blog-section-<?= $position ?>"><?= e($block['text']) ?></h2><?php endif;break;case 'quote': ?><blockquote><p><?= e($block['text']) ?></p></blockquote><?php break;case 'link': ?><p><a class="blog-read" href="<?= e(str_starts_with($block['url'],'/')?$base_url.$block['url']:$block['url']) ?>"><?= e($block['text']) ?></a></p><?php break;case 'code': ?><pre><code><?= e($block['text']) ?></code></pre><?php break;case 'image': ?><figure><img src="<?= e(BlogView::media($base_url,$block['src'])) ?>" alt="<?= e($block['alt']) ?>" loading="lazy"><figcaption><?= e($block['caption']) ?></figcaption></figure><?php break;case 'list': if ($block['ordered']): ?><ol><?php else: ?><ul><?php endif;foreach ($block['items'] as $item): ?><li><?= e($item) ?></li><?php endforeach;if ($block['ordered']): ?></ol><?php else: ?></ul><?php endif;break;endswitch;endforeach; ?>
<div class="blog-chips" aria-label="Tags"><?php foreach ($article['tags'] as $tag): ?><a rel="tag" href="<?= e(BlogView::url($base_url,'list',['tag'=>$tag])) ?>">#<?= e($catalog['tags'][$tag]['name']) ?></a><?php endforeach; ?></div>
<?php if ($author!==null): ?><section class="blog-author" itemprop="author" itemscope itemtype="https://schema.org/Person"><?php if ($author['image']!==''): ?><img itemprop="image" src="<?= e(BlogView::media($base_url,$author['image'])) ?>" alt="" width="64" height="64" loading="lazy"><?php endif; ?><div><h2><a href="<?= e(BlogView::url($base_url,'list',['author'=>$author['id']])) ?>"><span itemprop="name"><?= e($author['name']) ?></span></a></h2><p itemprop="description"><?= e($author['bio']) ?></p><?php if ($author['url']!==''): ?><a itemprop="url" href="<?= e($author['url']) ?>" rel="author noopener">Author profile ↗</a><?php endif; ?></div></section><?php endif; ?>
<nav class="blog-links" aria-label="Share article"><a href="<?= e('mailto:?'.http_build_query(['subject'=>$article['title'],'body'=>$contentMetadata['canonical']],'','&',PHP_QUERY_RFC3986)) ?>">Share by email</a><a href="<?= e($contentMetadata['canonical']) ?>">Permanent link</a></nav></div></div>
</article>
<?php if (!$blogModel['preview']&&$blogSettings['discussion']['enabled']): ?><section class="blog-comments" id="comments"><h2>Discussion</h2><?php if (($_GET['submitted']??null)==='1'): ?><p class="blog-notice" role="status">Thank you. Comments appear only after moderation.</p><?php endif; ?><?php foreach ($blogModel['comments'] as $comment): ?><article class="blog-comment"><h3><?= e($comment['name']) ?></h3><time datetime="<?= e($comment['createdAt']) ?>"><?= e(substr($comment['createdAt'],0,10)) ?></time><p><?= e($comment['body']) ?></p></article><?php endforeach; ?><form class="blog-comment-form" method="post" action="<?= e(BlogView::url($base_url,'comment')) ?>"><h3>Join the conversation</h3><p>Your name and message become public only after approval. No email address is requested.</p><input type="hidden" name="csrf_token" value="<?= e(Security::token()) ?>"><input type="hidden" name="article" value="<?= e($article['id']) ?>"><label>Your name<input name="name" maxlength="100" required autocomplete="name"></label><label>Comment<textarea name="body" rows="5" maxlength="<?= $blogSettings['discussion']['maxLength'] ?>" required></textarea></label><div class="blog-honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="blog-consent"><input type="checkbox" name="consent" value="1" required>I consent to publishing the name and message supplied above.</label><button type="submit">Submit for moderation</button></form></section><?php endif; ?>
<?php if (!$blogModel['preview']&&$blogModel['related']!==[]): ?><section class="blog-related"><h2>Keep reading</h2><div class="blog-grid"><?php foreach ($blogModel['related'] as $item) $card($item); ?></div></section><?php endif; ?>
<?php endif; ?></div></section>
